  ["    while let Some(n) = q.pop_front() {\n        order.push(n);\n        for &m in &g[&n] {\n            // adds m; true only if it was not there yet\n            if seen.___(m) { q.push_back(m); }\n        }\n    }\n"] = "    while let Some(n) = q.pop_front() {\n        order.push(n);\n        for &m in &g[&n] {\n            // añade m; true solo si aún no estaba\n            if seen.___(m) { q.push_back(m); }\n        }\n    }\n",
