  ['#[derive(Serialize, Deserialize)]\nstruct Order {\n    #[serde(___ = "dish")]\n    name: String,\n    qty: u32,\n}\n// {"dish":"toast","qty":2} now fills name\n'] = '#[derive(Serialize, Deserialize)]\nstruct Order {\n    #[serde(___ = "dish")]\n    name: String,\n    qty: u32,\n}\n// {"dish":"toast","qty":2} ahora rellena name\n',
  ['#[derive(Serialize, Deserialize)]\nstruct Order {\n    name: String,\n    #[serde(___ = "Option::is_none")]\n    note: Option<String>,\n}\n// None -> {"name":"toast"}   Some -> {"name":..,"note":..}\n'] = '#[derive(Serialize, Deserialize)]\nstruct Order {\n    name: String,\n    #[serde(___ = "Option::is_none")]\n    note: Option<String>,\n}\n// None -> {"name":"toast"}   Some -> {"name":..,"note":..}\n',
