  ["$ cargo ___ reqwest --features json\n    Updating crates.io index\n      Adding reqwest v0.12 to dependencies\n"] = "$ cargo ___ reqwest --features json\n    Updating crates.io index\n      Adding reqwest v0.12 to dependencies\n",
