  ["%v value, %+v with names, %#v as Go syntax, %T the type."] = "%v valor, %+v con nombres, %#v como sintaxis Go, %T el tipo.",
  ["%v with a plus. %#v adds the type name too; %T prints only the type."] = "%v con un más. %#v añade también el nombre del tipo; %T imprime solo el tipo.",
  ["%w builds a chain. %v would flatten it to text and lose the cause."] = "%w construye una cadena. %v la aplanaría a texto y perdería la causa.",
  ["&'a str: the output lives at least as long as the shorter of a and b. Lifetimes describe; they never extend anything."] = "&'a str: la salida vive al menos tanto como el más corto de a y b. Los lifetimes describen; nunca alargan nada.",
  ["&'static str lives for the whole program. String literals are 'static; a returned reference with no input to borrow from must be too."] = "&'static str vive todo el programa. Los literales de string son 'static; una referencia devuelta sin entrada de la que prestar también debe serlo.",
  ["&String is a shared borrow: read only, any number at once, the owner keeps the value."] = "&String es un préstamo compartido: solo lectura, tantos como quieras a la vez, el dueño conserva el valor.",
  ["&T{} is the usual way to make a pointer to a struct. p.Field works without (*p)."] = "&T{} es la forma habitual de crear un puntero a un struct. p.Field funciona sin (*p).",
  ["&dyn Cook is a trait object: a pointer plus a vtable. Go interfaces work the same way underneath."] = "&dyn Cook es un trait object: un puntero más una vtable. Las interfaces de Go funcionan igual por debajo.",
  ["&mut a. While r lives, no other borrow of a may exist: exactly 1 &mut, or many &, never both."] = "&mut a. Mientras r viva, no puede existir otro préstamo de a: exactamente 1 &mut, o muchos &, nunca ambos.",
  ["&prices[1..3] is a slice of type &[i32]: a borrowed window, no copy. [1..] and [..2] also work."] = "&prices[1..3] es un slice de tipo &[i32]: una ventana prestada, sin copia. [1..] y [..2] también funcionan.",
  ["&str is a view into text; String owns it. Take &str in parameters, return String when you build new text. The receipt prints once."] = "&str es una vista al texto; String es su dueño. Recibe &str en parámetros, devuelve String cuando construyes texto nuevo. El recibo se imprime una vez.",
  ["(ok, err). Check err before using ok. The gate opens."] = "(ok, err). Comprueba err antes de usar ok. El torniquete se abre.",
  ["*Order is a pointer. Methods that change the struct use a *T receiver."] = "*Order es un puntero. Los métodos que cambian el struct usan un receptor *T.",
  ["*http.Request is everything the client sent. Query().Get reads ?item=."] = "*http.Request es todo lo que envió el cliente. Query().Get lee ?item=.",
  ["--release turns on opt-level 3 and drops debug checks. Plain cargo build is for development."] = "--release activa opt-level 3 y quita las comprobaciones de debug. cargo build a secas es para desarrollo.",
  ["...int is variadic. Call it with sum(a, b, c) or spread a slice: sum(fares...)."] = "...int es variádico. Llámalo con sum(a, b, c) o expande un slice: sum(fares...).",
  [".await yields to the runtime until the Future is ready. Forget it and nothing runs."] = ".await cede al runtime hasta que el Future está listo. Olvídalo y nada se ejecuta.",
  ['// "abc" is not a number: fall back to zero coins.\nlet coins: u32 = "abc".parse().___(0);\n'] = '// "abc" no es un número: vuelve a cero monedas.\nlet coins: u32 = "abc".parse().___(0);\n',
  ["// &Option<T> to Option<&T>: a borrow, not a move.\nfn root_val(tree: &Link) -> Option<i32> {\n    tree.___().map(|n| n.val)\n}\n"] = "// De &Option<T> a Option<&T>: un préstamo, no un move.\nfn root_val(tree: &Link) -> Option<i32> {\n    tree.___().map(|n| n.val)\n}\n",
  ['// Any cook must give a name; greet comes for free.\n___ Cook {\n    fn name(&self) -> String;\n    fn greet(&self) -> String {\n        format!("{} at the pass", self.name())\n    }\n}\n'] = '// Todo cocinero debe dar un nombre; greet viene gratis.\n___ Cook {\n    fn name(&self) -> String;\n    fn greet(&self) -> String {\n        format!("{} at the pass", self.name())\n    }\n}\n',
  ["// Ask the compiler to write .clone() for Order.\n#[___(Clone, Debug)]\nstruct Order {\n    bun: String,\n    qty: u32,\n}\n"] = "// Pide al compilador que escriba .clone() para Order.\n#[___(Clone, Debug)]\nstruct Order {\n    bun: String,\n    qty: u32,\n}\n",
  ['// Cargo.toml: [dependencies] has this crate at version 1\nuse ___::Error;\n#[derive(Debug, Error)]\nenum OrderError {\n    #[error("order is empty")]\n    Empty,\n}\n'] = '// Cargo.toml: [dependencies] tiene este crate en la versión 1\nuse ___::Error;\n#[derive(Debug, Error)]\nenum OrderError {\n    #[error("order is empty")]\n    Empty,\n}\n',
  ['// Cargo.toml: tokio = {version="1", features=["full"]}\n#[___]\nasync fn main() {\n    let eta = fetch_eta(7).await;\n    println!("{eta} min");\n}\n'] = '// Cargo.toml: tokio = {version="1", features=["full"]}\n#[___]\nasync fn main() {\n    let eta = fetch_eta(7).await;\n    println!("{eta} min");\n}\n',
  ["// Debug + Display are done, so the body can stay empty\nimpl ___ for OrderError {}\n"] = "// Debug + Display ya están, así que el cuerpo puede quedar vacío\nimpl ___ for OrderError {}\n",
  ['// Grill and Wok in one Vec: each boxed as a trait object.\nlet crew: Vec<___> = vec![Box::new(Grill), Box::new(Wok)];\nfor c in &crew { println!("{}", c.greet()); }\n'] = '// Grill y Wok en un solo Vec: cada uno en un Box como trait object.\nlet crew: Vec<___> = vec![Box::new(Grill), Box::new(Wok)];\nfor c in &crew { println!("{}", c.greet()); }\n',
  ['// In the terminal, inside the project folder:\n//   $ cargo ___\n// Compiles target/debug/express and starts it.\nfn main() {\n    println!("Lucky Mac Express");\n}\n'] = '// En la terminal, dentro de la carpeta del proyecto:\n//   $ cargo ___\n// Compila target/debug/express y lo arranca.\nfn main() {\n    println!("Lucky Mac Express");\n}\n',
  ['// Keep every handle so the pass can wait for every cook.\nlet mut hs: Vec<___<()>> = Vec::new();\nfor id in 0..3 {\n    hs.push(thread::spawn(move || println!("cook {id}")));\n}\nfor h in hs { h.join().unwrap(); }\n'] = '// Guarda cada handle para que el pase pueda esperar a cada cocinero.\nlet mut hs: Vec<___<()>> = Vec::new();\nfor id in 0..3 {\n    hs.push(thread::spawn(move || println!("cook {id}")));\n}\nfor h in hs { h.join().unwrap(); }\n',
  ["// Not every table has an order yet.\nfn find(orders: &[(u32, &str)], t: u32) -> ___<String> {\n    for (n, item) in orders {\n        if *n == t { return Some(item.to_string()); }\n    }\n    None\n}\n"] = "// No todas las mesas tienen pedido todavía.\nfn find(orders: &[(u32, &str)], t: u32) -> ___<String> {\n    for (n, item) in orders {\n        if *n == t { return Some(item.to_string()); }\n    }\n    None\n}\n",
  ['// Nothing here tells parse which number type to build.\nlet qty = "12".parse___().unwrap();\nlet total = qty * 18;\n'] = '// Nada aquí le dice a parse qué tipo numérico construir.\nlet qty = "12".parse___().unwrap();\nlet total = qty * 18;\n',
  ["// One counter, many cooks: one writer at a time.\nlet sold = Arc::new(___::new(0u32));\n"] = "// Un contador, muchos cocineros: un escritor a la vez.\nlet sold = Arc::new(___::new(0u32));\n",
  ["// Only types with this marker may move to another thread.\nfn ship<T: ___ + 'static>(t: T) {\n    thread::spawn(move || drop(t));\n}\nship(Arc::new(5));    // ok: Arc is thread-safe\n// ship(Rc::new(5));  // error: Rc is not\n"] = "// Solo los tipos con este marcador pueden moverse a otro thread.\nfn ship<T: ___ + 'static>(t: T) {\n    thread::spawn(move || drop(t));\n}\nship(Arc::new(5));    // ok: Arc es thread-safe\n// ship(Rc::new(5));  // error: Rc no lo es\n",
  ['// Peek without waiting: the till must keep beeping.\nmatch rx.___() {\n    Ok(order) => println!("got {order}"),\n    Err(_) => println!("nothing yet"),\n}\n'] = '// Mira sin esperar: la caja debe seguir pitando.\nmatch rx.___() {\n    Ok(order) => println!("got {order}"),\n    Err(_) => println!("nothing yet"),\n}\n',
  ['// Rc counts on one thread only; this one crosses threads.\nlet menu = ___::new(vec!["bun", "egg tart"]);\nlet m2 = menu.clone();\nthread::spawn(move || println!("{}", m2[0]));\n'] = '// Rc cuenta en un solo thread; este cruza threads.\nlet menu = ___::new(vec!["bun", "egg tart"]);\nlet m2 = menu.clone();\nthread::spawn(move || println!("{}", m2[0]));\n',
  ['// Same bound, written under the signature for long lists.\nfn show_all<T>(items: &[T])\n___\n    T: std::fmt::Display,\n{\n    for it in items { println!("{it}"); }\n}\n'] = '// El mismo bound, escrito bajo la firma para listas largas.\nfn show_all<T>(items: &[T])\n___\n    T: std::fmt::Display,\n{\n    for it in items { println!("{it}"); }\n}\n',
  ["// Take any Cook at all; the caller picks the concrete type.\nfn fire(c: ___ Cook) -> String {\n    c.greet()\n}\n"] = "// Acepta cualquier Cook; quien llama elige el tipo concreto.\nfn fire(c: ___ Cook) -> String {\n    c.greet()\n}\n",
  ['// The banner is baked into the binary for the whole run.\nfn banner() -> &___ str {\n    "Lucky Mac Express"\n}\n'] = '// El letrero va grabado en el binario durante toda la ejecución.\nfn banner() -> &___ str {\n    "Lucky Mac Express"\n}\n',
  ["// The child lives on the heap, behind a pointer.\ntype Link = Option<___<Node>>;\nstruct Node {\n    val: i32,\n    left: Link,\n    right: Link,\n}\n"] = "// El hijo vive en el heap, detrás de un puntero.\ntype Link = Option<___<Node>>;\nstruct Node {\n    val: i32,\n    left: Link,\n    right: Link,\n}\n",
  ['// The entry point of a binary crate.\nfn ___() {\n    println!("Lucky Mac Express");\n}\n'] = '// El punto de entrada de un crate binario.\nfn ___() {\n    println!("Lucky Mac Express");\n}\n',
  ["// The first line of a Go file.\npackage ___\nfunc hello() {}\n"] = "// La primera línea de un archivo Go.\npackage ___\nfunc hello() {}\n",
  ['// The pass holds three trays: send blocks when full.\nlet (tx, rx) = mpsc::___(3);\ntx.send("tray").unwrap();\n'] = '// El pase aguanta tres bandejas: send bloquea cuando está lleno.\nlet (tx, rx) = mpsc::___(3);\ntx.send("tray").unwrap();\n',
  ["// The receipt only borrows the name: say so on the struct.\nstruct Receipt___ {\n    name: &'a str,\n    total: u32,\n}\n"] = "// El recibo solo toma prestado el nombre: dilo en el struct.\nstruct Receipt___ {\n    name: &'a str,\n    total: u32,\n}\n",
  ["// The tea thread hands back a number when it is done.\nlet tea = thread::spawn(|| 3 * 60);\n// Wait for it and take the result out of the handle.\nlet secs: u32 = tea.___().unwrap();\n"] = "// El thread del té devuelve un número cuando termina.\nlet tea = thread::spawn(|| 3 * 60);\n// Espéralo y saca el resultado del handle.\nlet secs: u32 = tea.___().unwrap();\n",
  ['// The till gives change back, or a message.\nfn pay(cash: u32, price: u32) -> ___<u32, String> {\n    if cash < price {\n        return Err("not enough cash".to_string());\n    }\n    Ok(cash - price)\n}\n'] = '// La caja devuelve el cambio, o un mensaje.\nfn pay(cash: u32, price: u32) -> ___<u32, String> {\n    if cash < price {\n        return Err("not enough cash".to_string());\n    }\n    Ok(cash - price)\n}\n',
  ["// Two buns from one tray: the winner lives as long as both.\nfn longest<'a>(a: &'a str, b: &'a str) -> &___ str {\n    if a.len() >= b.len() { a } else { b }\n}\n"] = "// Dos bollos de una bandeja: el ganador vive tanto como ambos.\nfn longest<'a>(a: &'a str, b: &'a str) -> &___ str {\n    if a.len() >= b.len() { a } else { b }\n}\n",
  ['// a literal is a &str; the kiosk needs its own copy\nlet shop = String::___("Lucky Mac Express");\nlet label: &str = &shop;\n'] = '// un literal es un &str; el kiosco necesita su propia copia\nlet shop = String::___("Lucky Mac Express");\nlet label: &str = &shop;\n',
  ["// b'a' is the byte 97. Subtracting it maps a..z onto 0..26.\n// An array index must be the pointer-sized unsigned type.\nlet mut count = [0i32; 26];\nfor c in \"muffin\".bytes() {\n    count[(c - b'a') as ___] += 1;\n}\n"] = "// b'a' es el byte 97. Restarlo mapea a..z sobre 0..26.\n// Un índice de array debe ser el entero sin signo del puntero.\nlet mut count = [0i32; 26];\nfor c in \"muffin\".bytes() {\n    count[(c - b'a') as ___] += 1;\n}\n",
  ['// both futures make progress on this task at once\nlet (a, b) = tokio::___!(fetch_eta(1), fetch_eta(2));\nprintln!("rider A {a} min, rider B {b} min");\n'] = '// ambos futures avanzan en esta tarea a la vez\nlet (a, b) = tokio::___!(fetch_eta(1), fetch_eta(2));\nprintln!("rider A {a} min, rider B {b} min");\n',
  ["// calling this does nothing yet; it hands back a Future\n___ fn fetch_eta(order_id: u32) -> u32 {\n    tokio::time::sleep(Duration::from_millis(200)).await;\n    order_id % 10 + 5\n}\n"] = "// llamar a esto aún no hace nada; devuelve un Future\n___ fn fetch_eta(order_id: u32) -> u32 {\n    tokio::time::sleep(Duration::from_millis(200)).await;\n    order_id % 10 + 5\n}\n",
  ["// go f() starts a ___\n// thousands of them are cheap\n"] = "// go f() lanza una ___\n// miles de ellas salen baratas\n",
  ["// merge(l, r): both slices are already sorted\nlet (mut i, mut j, mut out) = (0, 0, Vec::new());\nwhile i < l.len() && j < r.len() {\n    if l[i] ___ r[j] { out.push(l[i]); i += 1; }\n    else { out.push(r[j]); j += 1; }\n}\nout.extend(&l[i..]); out.extend(&r[j..]);\n"] = "// merge(l, r): los dos slices ya están ordenados\nlet (mut i, mut j, mut out) = (0, 0, Vec::new());\nwhile i < l.len() && j < r.len() {\n    if l[i] ___ r[j] { out.push(l[i]); i += 1; }\n    else { out.push(r[j]); j += 1; }\n}\nout.extend(&l[i..]); out.extend(&r[j..]);\n",
  ['// position gives an Option; the till wants a Result.\nfn find(menu: &[&str], w: &str) -> Result<usize, String> {\n    menu.iter()\n        .position(|m| *m == w)\n        .___("not on the menu".to_string())\n}\n'] = '// position da un Option; la caja quiere un Result.\nfn find(menu: &[&str], w: &str) -> Result<usize, String> {\n    menu.iter()\n        .position(|m| *m == w)\n        .___("not on the menu".to_string())\n}\n',
  ["// returns a JoinHandle; the task runs on the pool now\nlet handle = tokio::___(async { fetch_eta(3).await });\nprint_menu().await;\nlet eta = handle.await?;\n"] = "// devuelve un JoinHandle; la tarea ya corre en el pool\nlet handle = tokio::___(async { fetch_eta(3).await });\nprint_menu().await;\nlet eta = handle.await?;\n",
  ["// starts a line comment. /// is a doc comment that cargo doc turns into pages."] = "// empieza un comentario de línea. /// es un comentario de documentación que cargo doc convierte en páginas.",
  ['// the caller only learns: it is some Iterator of &str\nfn free_riders() -> ___ Iterator<Item = &\'static str> {\n    ["Wing", "Fai"].into_iter().filter(|r| *r != "Fai")\n}\n'] = '// quien llama solo sabe: es algún Iterator de &str\nfn free_riders() -> ___ Iterator<Item = &\'static str> {\n    ["Wing", "Fai"].into_iter().filter(|r| *r != "Fai")\n}\n',
  ['// the mall has five floors of pickup lockers\nfor floor in 1___5 {\n    println!("checking locker on floor {floor}");\n}\n// prints 1, 2, 3, 4, 5\n'] = '// el centro comercial tiene cinco pisos de taquillas de recogida\nfor floor in 1___5 {\n    println!("checking locker on floor {floor}");\n}\n// imprime 1, 2, 3, 4, 5\n',
  ['// three characters, three bytes each in UTF-8\nlet district = "銅鑼灣";\nlet n = district.___();\nassert_eq!(n, 9);\n'] = '// tres caracteres, tres bytes cada uno en UTF-8\nlet district = "銅鑼灣";\nlet n = district.___();\nassert_eq!(n, 9);\n',
  ["// two_sum: value -> index in a HashMap, one pass, O(n)\nlet mut seen = HashMap::new();\nfor (i, &x) in nums.iter().enumerate() {\n    let want = target - x;\n    if seen.___(&want) { return Some((seen[&want], i)); }\n    seen.insert(x, i);\n}\n"] = "// two_sum: valor -> índice en un HashMap, una pasada, O(n)\nlet mut seen = HashMap::new();\nfor (i, &x) in nums.iter().enumerate() {\n    let want = target - x;\n    if seen.___(&want) { return Some((seen[&want], i)); }\n    seen.insert(x, i);\n}\n",
  ["// worker(id, rx): the let drops the lock guard at the\n// semicolon, so the job runs with the rail unlocked.\nloop {\n    let msg = rx.lock().unwrap().___();\n    let Ok(job) = msg else { break };  // Err: senders gone\n    job();\n}\n"] = "// worker(id, rx): el let suelta el guard del lock en el\n// punto y coma, así el trabajo corre con el riel libre.\nloop {\n    let msg = rx.lock().unwrap().___();\n    let Ok(job) = msg else { break };  // Err: no hay emisores\n    job();\n}\n",
  ["//go:embed puts files in the binary: string, []byte or embed.FS."] = "//go:embed mete archivos en el binario: string, []byte o embed.FS.",
  ["0..3 stops before 3. Which range operator includes the last number?"] = "0..3 se detiene antes del 3. ¿Qué operador de rango incluye el último número?",
  ["06:40. Causeway Bay. Alex wants a muffin, a hash brown and coffee. The flat's door kiosk will not unlock until the Go file compiles."] = "06:40. Causeway Bay. Alex quiere un muffin, un hash brown y café. El kiosco de la puerta del apartamento no se abre hasta que el archivo Go compile.",
  ["08:10. Breakfast done. The owner wants a delivery app before the lunch rush. First ticket: the signboard shows 銅鑼灣 wrong, because a Go string is bytes, not characters."] = "08:10. Desayuno terminado. El dueño quiere una app de reparto antes del ajetreo del almuerzo. Primer ticket: el letrero muestra 銅鑼灣 mal, porque un string de Go son bytes, no caracteres.",
  ["1-7 jump straight in.   Q quest.   TAB Go/Rust.   F3 language.   F4 sound.   ESC quit."] = "1-7 entrar directo.   Q misión.   TAB Go/Rust.   F3 idioma.   F4 sonido.   ESC salir.",
  ["1..=3 is 1, 2, 3. for in Rust walks anything iterable: ranges, Vec, iterators."] = "1..=3 es 1, 2, 3. En Rust, for recorre cualquier cosa iterable: rangos, Vec, iteradores.",
  ['1..=5 is RangeInclusive; 1..5 stops at 4. Also in patterns: 1..=5 => "low".'] = '1..=5 es RangeInclusive; 1..5 se detiene en 4. También en patrones: 1..=5 => "low".',
  ["13:00. CODE RUSH, the live coding show on the Times Square screen. A crowd, a buzzer, seven rounds. Answer without a miss to keep the combo. Round one: recursion, and why fib needs a memo."] = "13:00. CODE RUSH, el programa de coding en vivo en la pantalla de Times Square. Público, un timbre, siete rondas. Responde sin fallar para mantener el combo. Ronda uno: recursión, y por qué fib necesita un memo.",
  ["15:00. Lunch is done at Lucky Mac. Mei's laptop shows the Times Square branch: every kiosk of Lucky Mac Express is frozen on a Rust file with no main. Alex knows Go. Mei knows Rust. They start walking."] = "15:00. Se acabó el almuerzo en Lucky Mac. El portátil de Mei muestra la sucursal de Times Square: todos los kioscos de Lucky Mac Express están congelados en un archivo Rust sin main. Alex sabe Go. Mei sabe Rust. Empiezan a caminar.",
  ["15:08. The tram stop on Percival Street. The next-tram sign runs a tiny Rust program and it will not compile: someone tried to change a value that was never marked mut. Mei fixes it while Alex reads the error messages out loud."] = "15:08. La parada del tranvía en Percival Street. El letrero del próximo tranvía corre un programa Rust diminuto y no compila: alguien intentó cambiar un valor que nunca se marcó mut. Mei lo arregla mientras Alex lee los errores en voz alta.",
  ["15:15. The underpass at Causeway Bay MTR exit A. The Lucky Mac Express ad gate should show muffin, coffee or set as people walk past, but its match has a hole and the loop never ends. Mei counts the cases on her fingers."] = "15:15. El paso subterráneo de la salida A del MTR de Causeway Bay. La puerta publicitaria de Lucky Mac Express debería mostrar muffin, café o menú al pasar la gente, pero su match tiene un hueco y el bucle nunca termina. Mei cuenta los casos con los dedos.",
  ["15:20. The footbridge over Canal Road, Times Square's clock ahead. The Express delivery board on the bridge shows the price of every set, but the pricing function returns nothing and the seat finder crashes on an empty table. Alex tries the Rust himself for the first time."] = "15:20. La pasarela sobre Canal Road, el reloj de Times Square al frente. El tablero de entregas del Express en el puente muestra el precio de cada menú, pero la función de precios no devuelve nada y el buscador de asientos se cae con una mesa vacía. Alex prueba el Rust por primera vez él mismo.",
  ["15:25. The atrium of Times Square, the crab sticker on the Express order kiosk. The kiosk prints a receipt, then tries to read the same String again and the compiler says: value used after move. Mei explains who owns the tray."] = "15:25. El atrio de Times Square, la pegatina del cangrejo en el kiosco de pedidos del Express. El kiosco imprime un recibo, luego intenta leer el mismo String otra vez y el compilador dice: value used after move. Mei explica quién es el dueño de la bandeja.",
  ["15:30. The queue outside Lucky Mac Express, twelve people and a crab sticker on the board. The board should list every order's price and count the muffins per table, but the Vec is never pushed to and the HashMap panics on a missing key. Siu Ming waves them to the front."] = "15:30. La fila frente a Lucky Mac Express, doce personas y una pegatina de cangrejo en el tablero. El tablero debería listar el precio de cada pedido y contar los muffins por mesa, pero nunca se hace push al Vec y el HashMap hace panic con una clave que falta. Siu Ming les hace señas para pasar al frente.",
  ["15:35. The counter of Lucky Mac Express at last, the crab sticker smiling on the till. The till keeps orders as loose tuples and cannot print them, and a size of Medium sneaks in that the kitchen does not know. Siu Ming needs an Order type before the afternoon set can be sold."] = "15:35. Por fin el mostrador de Lucky Mac Express, la pegatina del cangrejo sonriendo en la caja. La caja guarda los pedidos como tuplas sueltas y no puede imprimirlos, y se cuela un tamaño Medium que la cocina no conoce. Siu Ming necesita un tipo Order antes de poder vender la merienda.",
  ["16:00. Lucky Mac Express, Times Square. The till took a coin it could not parse and froze on a red Err. Siu Ming has a queue; Alex has to learn how Rust hands errors back."] = "16:00. Lucky Mac Express, Times Square. La caja recibió una moneda que no pudo parsear y se congeló en un Err rojo. Siu Ming tiene fila; Alex tiene que aprender cómo Rust devuelve los errores.",
  ["16:10. The Express kitchen. Chef Bo's pass runs every station through one Rust program, but the grill and the wok speak different types and the order board shows nothing. A trait gives them one shared voice."] = "16:10. La cocina del Express. El pase de Chef Bo dirige cada estación con un solo programa Rust, pero la parrilla y el wok hablan tipos distintos y el tablero de pedidos no muestra nada. Un trait les da una voz común.",
  ["16:20. The kiosk in the mall corridor has one price list in u32 and one weight list in f64, and two copies of every function. The crab on the screen sulks. Generics fold them into one."] = "16:20. El kiosco del pasillo del centro comercial tiene una lista de precios en u32 y una de pesos en f64, y dos copias de cada función. El cangrejo de la pantalla está de morros. Los genéricos las funden en una.",
  ["16:30. The set table by the window. The receipt printer holds a reference to a name that was freed one line earlier and Rust refuses to build. Alex learns to say how long a borrow lives."] = "16:30. La mesa del menú junto a la ventana. La impresora de recibos guarda una referencia a un nombre liberado una línea antes y Rust se niega a compilar. Alex aprende a decir cuánto vive un préstamo.",
  ["16:40. Three orders, one cook, one thread: the pineapple buns wait while the kettle boils. Chef Bo wants the grill, the kettle and the pass to run at the same time. Rust threads are real OS threads; no go keyword here."] = "16:40. Tres pedidos, un cocinero, un thread: los bollos de piña esperan mientras hierve el agua. Chef Bo quiere que la parrilla, el hervidor y el pase corran a la vez. Los threads de Rust son threads reales del sistema; aquí no hay palabra go.",
  ["16:50. Two tills at Lucky Mac Express and one kitchen. Orders sit in a shared Vec that both tills scribble on and the kitchen never sees. Mei replaces the Vec with a channel: many senders, one receiver."] = "16:50. Dos cajas en Lucky Mac Express y una cocina. Los pedidos están en un Vec compartido en el que garabatean ambas cajas y que la cocina nunca ve. Mei reemplaza el Vec por un channel: muchos emisores, un receptor.",
  ["17:00. Last hour before the tea set. Both tills bump one sold counter from two threads and the total drifts. Rc will not even compile across threads; Mei reaches for Arc, Mutex and one atomic. Get it right and the afternoon tea set is yours."] = "17:00. Última hora antes de la merienda. Las dos cajas suben un mismo contador de ventas desde dos threads y el total se desvía. Rc ni siquiera compila entre threads; Mei recurre a Arc, Mutex y un atómico. Hazlo bien y la merienda es tuya.",
  ["17:00. Lucky Mac Express, Times Square. The receipt printer writes the shop name as 銅鑼 and a broken square. Someone sliced a String by byte count. Mei opens ticket one."] = "17:00. Lucky Mac Express, Times Square. La impresora de recibos escribe el nombre de la tienda como 銅鑼 y un cuadrado roto. Alguien cortó un String por número de bytes. Mei abre el ticket uno.",
  ["17:10. The till at Lucky Mac Express unwraps every parse. One bad keypad entry and the drawer prints a stack trace instead of a receipt. Siu Ming wants a real error type."] = "17:10. La caja de Lucky Mac Express hace unwrap de cada parse. Una entrada mala en el teclado y el cajón imprime un stack trace en vez de un recibo. Siu Ming quiere un tipo de error de verdad.",
  ["17:20. The kitchen printer at Lucky Mac Express runs a hand-written index loop. It skips the first dish and prints the last one twice. Chef Bo hands Alex ticket three: iterators."] = "17:20. La impresora de cocina de Lucky Mac Express usa un bucle de índices escrito a mano. Se salta el primer plato e imprime el último dos veces. Chef Bo le pasa a Alex el ticket tres: iteradores.",
  ['17:30. Under the mall atrium screens, the rider app and the kitchen disagree on field names, and every order arrives as "name": null. Ticket four: teach the structs to speak JSON with serde.'] = '17:30. Bajo las pantallas del atrio del centro comercial, la app de repartidores y la cocina no se ponen de acuerdo en los nombres de campo, y cada pedido llega como "name": null. Ticket cuatro: enseña a los structs a hablar JSON con serde.',
  ["17:40. Russell Street. Riders idle by the tram stop while the delivery backend fetches ETAs one by one, blocking on each. Ticket five: make the calls async and run them together on tokio."] = "17:40. Russell Street. Los repartidores esperan junto a la parada del tranvía mientras el backend de reparto pide los ETA uno por uno, bloqueándose en cada uno. Ticket cinco: haz las llamadas async y córrelas juntas en tokio.",
  ["17:50. The pickup queue at Lucky Mac Express is out the door and the new backend is still a folder of .rs files. Alex has go build in his fingers. Mei: in Rust it is all cargo."] = "17:50. La fila de recogida de Lucky Mac Express sale por la puerta y el nuevo backend sigue siendo una carpeta de archivos .rs. Alex tiene go build en los dedos. Mei: en Rust todo es cargo.",
  ["17:55. Lucky Mac Express, the set counter. The backend compiles, but Mei's review has six comments: this is 2015 Rust. Alex rewrites each one the modern way. Then it ships. SHIPPED."] = "17:55. Lucky Mac Express, el mostrador de menús. El backend compila, pero la revisión de Mei tiene seis comentarios: esto es Rust de 2015. Alex reescribe cada uno a la manera moderna. Y sale a producción. ENTREGADO.",
  ["19:00. CODE RUSH, the live coding show on the Times Square screen, evening edition: Rust. A crowd, a buzzer, seven rounds, Mei at the keyboard. No misses keeps the combo. Round one: recursion, and why fib needs a memo."] = "19:00. CODE RUSH, el programa de programación en directo en la pantalla de Times Square, edición de noche: Rust. Público, un pulsador, siete rondas, Mei al teclado. Sin fallos se mantiene el combo. Ronda uno: recursión, y por qué fib necesita un memo.",
  ["19:08. Round two, and the screen shows a tree of order numbers. Insert, walk in order, measure the height. In Rust a tree is a struct with two Option<Box<Node>> fields, and the compiler wants to know its size."] = "19:08. Ronda dos, y la pantalla muestra un árbol de números de pedido. Inserta, recórrelo en orden, mide la altura. En Rust un árbol es un struct con dos campos Option<Box<Node>>, y el compilador quiere saber su tamaño.",
  ["19:17. Round three puts the MTR map on the big screen: stations are nodes, lines are edges. Mei has to reach every station once. Wide first with a queue, then deep with a stack, and a HashSet so nobody loops forever."] = "19:17. La ronda tres pone el mapa del MTR en la pantalla grande: las estaciones son nodos, las líneas son aristas. Mei tiene que llegar a cada estación una vez. Primero a lo ancho con una cola, luego a lo hondo con una pila, y un HashSet para que nadie dé vueltas para siempre.",
  ["19:26. Round four is the chain: a linked list of order tickets, out on the street where the delivery riders queue. Each node owns the next one. Reverse it, walk it, find the middle, and never touch a raw pointer."] = "19:26. La ronda cuatro es la cadena: una lista enlazada de tickets de pedido, en la calle donde hacen cola los repartidores. Cada nodo posee al siguiente. Inviértela, recórrela, encuentra el medio, y sin tocar nunca un puntero crudo.",
  ["19:35. Round five, the shuffle. The screen dumps a hundred order prices in random order. Mei writes merge sort from memory, then the host wants the std spelling: stable, unstable, and a binary search on the result."] = "19:35. Ronda cinco, la barajada. La pantalla suelta cien precios de pedido en orden aleatorio. Mei escribe merge sort de memoria, y luego el presentador quiere la versión de std: estable, inestable, y una búsqueda binaria sobre el resultado.",
  ["19:44. Round six, the classics, back on the mall floor with the crowd pressing in. Two-sum, a palindrome, an anagram, a word count. Every one of them is a hash map or an array of 26, and every one is O(n)."] = "19:44. Ronda seis, los clásicos, de vuelta en la planta del centro comercial con el público apretando. Two-sum, un palíndromo, un anagrama, un conteo de palabras. Todos son un hash map o un array de 26, y todos son O(n).",
  ["19:55. The final, the one they always ask: N worker threads pull jobs from one channel. The Times Square screen shows the Lucky Mac Express kitchen as the diagram. Get the lock, the drop and the join right and the prize is HIRED."] = "19:55. La final, la que siempre preguntan: N threads worker sacan trabajos de un solo channel. La pantalla de Times Square muestra la cocina de Lucky Mac Express como diagrama. Acierta con el lock, el drop y el join y el premio es CONTRATADA.",
  ["7 streets. One language. Type the answers."] = "7 calles. Un lenguaje. Escribe las respuestas.",
  [":= declares and assigns. Type comes from the right-hand side."] = ":= declara y asigna. El tipo viene del lado derecho.",
  [":= infers the type. var names it. const never changes. int starts at 0."] = ":= infiere el tipo. var lo nombra. const nunca cambia. int empieza en 0.",
  ["< PREV"] = "< ANTERIOR",
  ["<-chan T and chan<- T let the compiler stop the wrong side from sending or closing."] = "<-chan T y chan<- T dejan que el compilador impida al lado equivocado enviar o cerrar.",
  ["? calls From::from on the error. Without the impl, use .map_err(OrderError::BadQty) by hand."] = "? llama a From::from sobre el error. Sin el impl, usa .map_err(OrderError::BadQty) a mano.",
  ["? on Option returns None when it sees None. The function type must be Option as well."] = "? en Option devuelve None cuando ve None. El tipo de la función también debe ser Option.",
  ["? unwraps Ok, or returns Err early from the function. Only works where the return type is Result or Option."] = "? desenvuelve Ok, o devuelve Err saliendo antes de la función. Solo funciona donde el tipo de retorno es Result u Option.",
  ["A String has one owner. Assigning moves it. & borrows, &mut borrows exclusively. Values drop at the end of their scope."] = "Un String tiene un solo dueño. Asignarlo lo mueve. & lo presta, &mut lo presta en exclusiva. Los valores se liberan al final de su scope.",
  ["A Vec is your Go slice. An array knows its length at compile time."] = "Un Vec es tu slice de Go. Un array conoce su longitud al compilar.",
  ["A bang. vec! and format! end the same way."] = "Un signo de exclamación. vec! y format! terminan igual.",
  ["A buffered channel blocks only when full. Unbuffered blocks on every send until someone receives."] = "Un channel con búfer solo bloquea al llenarse. Sin búfer bloquea en cada envío hasta que alguien recibe.",
  ["A buffered channel is a counting semaphore. golang.org/x/sync/semaphore is the weighted version."] = "Un channel con buffer es un semáforo contador. golang.org/x/sync/semaphore es la versión con pesos.",
  ["A call that can fail returns Result. Handle Err, or pass it up with ?."] = "Una llamada que puede fallar devuelve Result. Maneja Err, o pásalo arriba con ?.",
  ["A channel that holds 3 muffins before a send blocks. Fill: make(chan string, ___)"] = "Un channel que guarda 3 muffins antes de que un envío bloquee. Completa: make(chan string, ___)",
  ["A closure captures n. Each call to add(2) has its own n."] = "Un closure captura n. Cada llamada a add(2) tiene su propia n.",
  ["A cold coffee came back. The app says 'error' and nothing else."] = "Devolvieron un café frío. La app dice 'error' y nada más.",
  ["A compile-time value with an UPPER_CASE name and a required type. Which keyword?"] = "Un valor de compilación con nombre en MAYÚSCULAS y tipo obligatorio. ¿Qué palabra clave?",
  ["A constraint that allows int and every type built on int. Fill: ___int | ___float64"] = "Una restricción que permite int y todo tipo construido sobre int. Completa: ___int | ___float64",
  ["A cook locks the rail, pulls one ticket, releases. Which Receiver method blocks until a job arrives?"] = "Un cocinero bloquea el riel, saca un ticket, lo libera. ¿Qué método de Receiver bloquea hasta que llega un trabajo?",
  ["A crash you can catch in the same goroutine. Which pair: panic and ___?"] = "Un fallo que puedes atrapar en la misma goroutine. ¿Qué pareja: panic y ___?",
  ['A crate writes Display and Error for you from #[error("..")]. Its name?'] = 'Un crate escribe Display y Error por ti a partir de #[error("..")]. ¿Su nombre?',
  ["A customer typed 1x8 sets and the till printed a page of panic. Ticket two."] = "Un cliente escribió 1x8 menús y la caja imprimió una página de panic. Ticket dos.",
  ["A done signal that carries no data. Fill the element type: make(chan ___)"] = "Una señal de fin que no lleva datos. Completa el tipo del elemento: make(chan ___)",
  ["A dot, then the word for waiting. Only allowed inside an async block or fn."] = "Un punto, luego la palabra inglesa para esperar. Solo se permite dentro de un bloque o fn async.",
  ["A field with no name, only the type. That is embedding."] = "Un campo sin nombre, solo el tipo. Eso es embedding.",
  ["A fixed [26]int beats a map for lowercase ASCII. Then check every count == 0."] = "Un [26]int fijo supera a un map para ASCII en minúsculas. Luego comprueba que cada count == 0.",
  ["A fixed array of exactly 3 frames, size in the type. Fill: var frames ___"] = "Un array fijo de exactamente 3 frames, tamaño en el tipo. Completa: var frames ___",
  ["A fixed tray of three prices. The array type spells out its length. Which number?"] = "Una bandeja fija de tres precios. El tipo del array escribe su longitud. ¿Qué número?",
  ["A flag: dash then four letters. Works with run and build too."] = "Un flag: guion y cuatro letras. También funciona con run y build.",
  ["A function that can fail returns a value and an ___."] = "Una función que puede fallar devuelve un valor y un ___.",
  ["A function that can fail returns which type?"] = "¿Qué tipo devuelve una función que puede fallar?",
  ["A function that remembers n after ident returns. What is that function called?"] = "Una función que recuerda n después de que ident retorne. ¿Cómo se llama esa función?",
  ["A function that runs once before main, and nobody calls it. Its name?"] = "Una función que corre una vez antes de main y nadie la llama. ¿Su nombre?",
  ["A goroutine is cheap. Don't confuse it with a thread you create by hand."] = "Una goroutine es barata. No la confundas con un hilo creado a mano.",
  ["A heap pointer to a dyn trait: Box, angle brackets, dyn, the trait."] = "Un puntero al heap hacia un dyn trait: Box, ángulos, dyn, el trait.",
  ["A list is Option<Box<ListNode>>. take() moves a node out and leaves None. Reverse with prev and cur; slow and fast runners find the middle."] = "Una lista es Option<Box<ListNode>>. take() saca un nodo y deja None. Invierte con prev y cur; los corredores slow y fast encuentran el medio.",
  ["A loop that returns a value? Go cannot do that."] = "¿Un bucle que devuelve un valor? Go no puede hacer eso.",
  ['A map from string to int. Fill the type: prices := ___{"muffin": 18}'] = 'Un map de string a int. Completa el tipo: prices := ___{"muffin": 18}',
  ["A map is a hash table. comma-ok tells you if the key was there. delete removes it."] = "Un map es una tabla hash. comma-ok te dice si la clave estaba. delete la quita.",
  ["A map turns O(n^2) two-sum into O(n). Two pointers check a palindrome. A [26]int counts letters."] = "Un map convierte two-sum de O(n^2) en O(n). Dos punteros comprueban un palíndromo. Un [26]int cuenta letras.",
  ["A method on context.Context. Its channel closes on cancel."] = "Un método de context.Context. Su channel se cierra al cancelar.",
  ["A method that changes the order needs a pointer receiver. Fill: func (o ___) Add(p int)"] = "Un método que cambia el pedido necesita un receptor puntero. Completa: func (o ___) Add(p int)",
  ["A miss: compute it from the two smaller ones. Fill the second call: fib(___, memo)"] = "Un fallo: calcúlalo a partir de los dos menores. Completa la segunda llamada: fib(___, memo)",
  ["A move. Integers are Copy and stay valid; a String is moved and the old name dies. No double free, ever."] = "Un move. Los enteros son Copy y siguen válidos; un String se mueve y el nombre viejo muere. Nunca hay double free.",
  ["A name that cannot be assigned later. Which keyword?"] = "Un nombre que no se puede reasignar después. ¿Qué palabra clave?",
  ["A nil *Order stored in an interface. Is the interface == nil? It prints ___"] = "Un *Order nil guardado en una interface. ¿La interface == nil? Imprime ___",
  ["A nil map panics when you write to it. Allocate one: floors = ___(map[string]int)"] = "Un map nil hace panic al escribir en él. Reserva uno: floors = ___(map[string]int)",
