  ["A struct, so it comes as a pointer. r.Method, r.URL, r.Body."] = "Un struct, así que llega como puntero. r.Method, r.URL, r.Body.",
  ["A switch with no condition is Go's if-else chain. sort.SearchInts does this for you."] = "Un switch sin condición es la cadena if-else de Go. sort.SearchInts lo hace por ti.",
  ["A test function in order_test.go. Fill the name prefix: func ___(t *testing.T)"] = "Una función de test en order_test.go. Completa el prefijo del nombre: func ___(t *testing.T)",
