  ["An interface is (type, value). The type *Order is set, so it is not the nil interface."] = "Una interface es (tipo, valor). El tipo *Order está fijado, así que no es la interface nil.",
  ["An unbuffered send needs a receiver already waiting. Put the send in a goroutine or buffer the channel."] = "Un envío sin búfer necesita un receptor ya esperando. Pon el envío en una goroutine o dale búfer al channel.",
  ["Anagram: same letters, same counts. Lowercase ASCII only. How many slots does the counter array need?"] = "Anagrama: mismas letras, mismos conteos. Solo ASCII en minúsculas. ¿Cuántas casillas necesita el array contador?",
  ["And the size is an enum. Small or Large, nothing in between, the compiler makes sure."] = "Y el tamaño es un enum. Small o Large, nada en medio, el compilador se asegura.",
