  ["Do not block if nothing is ready. Which case label?"] = "No bloquees si nada está listo. ¿Qué etiqueta de case?",
  ["Don't share memory. Pass the hash brown on a channel."] = "No compartas memoria. Pasa el hash brown por un channel.",
  ["Double every quantity. How does a closure name its one parameter?"] = "Duplica cada cantidad. ¿Cómo nombra un closure su único parámetro?",
  ["ENTER  pick a street"] = "ENTER  elige una calle",
