  ['fn main() {\n    let prices = ___[18, 22, 25];   // Vec<i32> on the heap\n    println!("{}", prices[0]);\n}\n'] = 'fn main() {\n    let prices = ___[18, 22, 25];   // Vec<i32> en el heap\n    println!("{}", prices[0]);\n}\n',
